function n(a){if(!a)return"—";const t=new Date(a*1e3),e=r=>String(r).padStart(2,"0");return`${t.getFullYear()}-${e(t.getMonth()+1)}-${e(t.getDate())} ${e(t.getHours())}:${e(t.getMinutes())}`}function o(a){if(!a)return"—";const t=new Date(a*1e3),e=r=>String(r).padStart(2,"0");return`${e(t.getHours())}:${e(t.getMinutes())}`}function g(a){if(!a)return"—";const t=new Date(a*1e3),e=r=>String(r).padStart(2,"0");return`${e(t.getMonth()+1)}-${e(t.getDate())} ${e(t.getHours())}:${e(t.getMinutes())}`}export{g as a,o as b,n as f};
